def create_job_id():
    return str(uuid.uuid4())

def atoms_to_pdb(atoms):
    """Convert atoms list to PDB format"""
    pdb_lines = []
    for i, atom in enumerate(atoms, 1):
        pdb_lines.append(
            f"ATOM  {i:5d}  CA  ALA A{i:4d}    {atom['coords'][0]:8.3f}{atom['coords'][1]:8.3f}{atom['coords'][2]:8.3f}  1.00{atom.get('confidence', 0)*100:6.2f}           C"
        )
    pdb_lines.append("END")
    return "\n".join(pdb_lines)

@app.route('/api/alphafold3', methods=['POST'])
