        sequence = data.get('sequence')
        chains = data.get('chains')
        ligand_smiles = data.get('ligand_smiles')
        quantum_enhancement = data.get('quantum_enhancement', False)
        recycle_iterations = data.get('recycle_iterations', 3)

        # Determine interval
        if sequence:
            interval = genome.Interval('chr1', 1000000, 1000000 + len(sequence) * 3)
        elif chains and len(chains) > 0:
            interval = genome.Interval('chr1', 1000000, 1000000 + len(chains[0]) * 3)
        else:
            interval = genome.Interval('chr1', 1000000, 1001000)

