        output = dna_model.predict_interval(
            interval=interval,
            requested_outputs=[
                dna_client.OutputType.RNA_SEQ,
                dna_client.OutputType.DNASE,
                dna_client.OutputType.ATAC
            ],
            ontology_terms=['EFO:0002067']
        )

